insert into public.orbit_questions select * from jsonb_populate_recordset(null::public.orbit_questions, '[{"id": "enem-2023-90-geral", "year": 2023, "number": 90, "discipline": "ciencias-humanas", "language": null, "context": "", "prompt": "Não tinha outra filosofia. Nem eu. Não digo que a Universidade me não tivesse ensinado alguma; mas eu decorei-lhe só as fórmulas, o vocabulário, o esqueleto. Tratei-a como tratei o latim; embolsei três versos de Virgílio, dois de Horácio, uma dúzia de locuções morais e políticas, para as despesas da conversação. Tratei-os como tratei a história e a jurisprudência. Colhi de todas as cousas a fraseologia, a casca, a ornamentação.\nASSIS, M. Memórias póstumas do Brás Cubas. Belo Horizonte: Autêntica. 1999.\nA descrição crítica do personagem de Machado de Assis assemelha-se às características dos sofistas, contestados pelos filósofos gregos da Antiguidade, porque se mostra alinhada à", "alternatives": [{"letter": "A", "text": "Elaboração conceitual de entendimentos.", "file": null}, {"letter": "B", "text": "Utilização persuasiva do discurso.", "file": null}, {"letter": "C", "text": "Narração alegórica dos rapsodos.", "file": null}, {"letter": "D", "text": "Investigação empírica da physis.", "file": null}, {"letter": "E", "text": "Expressão pictográfica da pólis.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/90", "created_at": "2026-10-27T00:00:00Z"}, {"id": "enem-2023-91-geral", "year": 2023, "number": 91, "discipline": "ciencias-natureza", "language": null, "context": "O número de abelhas encontra-se em declínio em várias regiões do mundo, inclusive no Brasil, sendo que vários fatores contribuem para o colapso de suas colmeias. Nos Estados Unidos, bombas de sementes de espécies vegetais nativas têm sido utilizadas para combater o desaparecimento desses insetos. Elas são pequenas bolinhas recheadas com sementes, adubo e argila. Quando são arremessadas e ficam expostas ao sol e à chuva, germinam até mesmo em solo pouco fértil.\n\nDARAYA, V. Disponível em: http://planetasustentavel.abril.com.br.  \nAcesso em: 2 fev. 2015 (adaptado).", "prompt": "Esse método contribui para a preservação das abelhas porque", "alternatives": [{"letter": "A", "text": "Reduz sua predação", "file": null}, {"letter": "B", "text": "Reduz o uso de pesticidas.", "file": null}, {"letter": "C", "text": "Reduz a competição por abrigo.", "file": null}, {"letter": "D", "text": "Aumenta a oferta de alimento", "file": null}, {"letter": "E", "text": "Aumenta os locais de reprodução", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/91", "created_at": "2026-10-27T00:00:00Z"}, {"id": "enem-2023-92-geral", "year": 2023, "number": 92, "discipline": "ciencias-natureza", "language": null, "context": "Os mais antigos cozinhavam o feijão na panela de ferro a fim de acabar com a palidez de seus filhos. Alguns chegavam até a colocar um prego enferrujado nesse cozimento para liberar o ferro contido nele. Sabe-se que esse elemento pode ser encontrado na sua forma metálica ou iônica, sendo essencial para a manutenção da vida humana.", "prompt": "As estratégias citadas eram utilizadas com o objetivo de", "alternatives": [{"letter": "A", "text": "Tratar a diarreia.", "file": null}, {"letter": "B", "text": "Prevenir a anemia.", "file": null}, {"letter": "C", "text": "Evitar as verminoses.", "file": null}, {"letter": "D", "text": "Remediar o raquitismo", "file": null}, {"letter": "E", "text": "Combater a febre amarela.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/92", "created_at": "2026-10-27T00:00:00Z"}, {"id": "enem-2023-93-geral", "year": 2023, "number": 93, "discipline": "ciencias-humanas", "language": null, "context": "", "prompt": "A utilização de tecnologia nuclear é um tema bastante controverso, por causa do risco de acidentes graves, como aqueles ocorridos em Chernobyl (1986), em Goiânia (1987) e em Fukushima (2011). Apesar de muitas desvantagens, como a geração de resíduos tóxicos, a descontaminação ambiental dispendiosa em caso de acidentes e a utilização em armas nucleares, a geração de energia nuclear apresenta vantagens em comparação a outras fontes de energia.\nA geração dessa energia tem como característica:", "alternatives": [{"letter": "A", "text": "Formar resíduos facilmente recicláveis.", "file": null}, {"letter": "B", "text": "Promover o aumento do desmatamento.", "file": null}, {"letter": "C", "text": "Contribuir para a produção de chuva ácida.", "file": null}, {"letter": "D", "text": "Emitir gases tóxicos que são lançados no ambiente.", "file": null}, {"letter": "E", "text": "Produzir calor sem o consumo de combustíveis fósseis.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/93", "created_at": "2026-10-27T00:00:00Z"}, {"id": "enem-2023-94-geral", "year": 2023, "number": 94, "discipline": "ciencias-humanas", "language": null, "context": "Em uma indústria, o controle da dureza da água é importante quando ela é utilizada em caldeiras, uma vez que sais pouco solúveis, formados a partir de sulfatos e carbonatos, podem acumular-se no interior das tubulações, causando obstruções. Para avaliar a água utilizada nessa indústria, foram realizados testes de qualidade que consideraram os seauintes parâmetros:\n\n![](https://enem.dev/2023/questions/94/429989c0-d615-4e19-a5e6-838e81a6039c.png)", "prompt": "Qual teste deve ser considerado para controlar a formação desse tipo de obstrução de tubulações?", "alternatives": [{"letter": "A", "text": "1", "file": null}, {"letter": "B", "text": "2", "file": null}, {"letter": "C", "text": "3", "file": null}, {"letter": "D", "text": "4", "file": null}, {"letter": "E", "text": "5", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/94", "created_at": "2026-10-27T00:00:00Z"}, {"id": "enem-2023-95-geral", "year": 2023, "number": 95, "discipline": "ciencias-natureza", "language": null, "context": "", "prompt": "As aves apresentam dois tipos de músculos em seus corpos: vermelhos e brancos. Aves migratórias como garças, gansos e patos selvagens têm os músculos vermelhos bem desenvolvidos, com ampla rede de vasos sanguíneos.\nNas viagens por grandes distâncias, tais músculos são fundamentais, pois favorecem o(a)", "alternatives": [{"letter": "A", "text": "Execução de manobras.", "file": null}, {"letter": "B", "text": "Metabolismo corpóreo elevado.", "file": null}, {"letter": "C", "text": "Manutenção da aerodinâmica.", "file": null}, {"letter": "D", "text": "Deslocamento a grandes velocidades.", "file": null}, {"letter": "E", "text": "Capacidade de voo em grandes altitudes.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/95", "created_at": "2026-10-27T00:00:00Z"}, {"id": "enem-2023-96-geral", "year": 2023, "number": 96, "discipline": "ciencias-humanas", "language": null, "context": "", "prompt": "Existe no comércio um produto antimofo constituído por uma embalagem com tampa perfurada contendo cloreto de cálcio anidro, CaCI,. Uma vez aberto o lacre, essa substância absorve a umidade ambiente, transformando-se em cloreto de cálcio di-hidratado, CaCI, 2H,0. Considere a massa molar da água igual a 18 g mol-1, e a massa molar do cloreto de cálcio anidro igual a 111 g mol-1.\nNa hidratação da substância presente no antimofo, o ganho percentual, em massa, é mais próximo de", "alternatives": [{"letter": "A", "text": "14%", "file": null}, {"letter": "B", "text": "16%", "file": null}, {"letter": "C", "text": "24%", "file": null}, {"letter": "D", "text": "32%", "file": null}, {"letter": "E", "text": "75%", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/96", "created_at": "2026-10-27T00:00:00Z"}, {"id": "enem-2023-97-geral", "year": 2023, "number": 97, "discipline": "ciencias-humanas", "language": null, "context": "", "prompt": "Um garoto comprou vários abacates na feira, mas descobriu que eles não estavam maduros o suficiente para serem consumidos. Sua mãe recomendou que ele colocasse os abacates em um recipiente fechado, pois isso aceleraria seu amadurecimento. Com certa dúvida, o garoto realizou esta experiência: colocou alguns abacates no recipiente e deixou os demais em uma fruteira aberta. Surpreendendo-se, ele percebeu que os frutos que estavam no recipiente fechado amadureceram mais rapidamente.\nA aceleração desse processo é causada por", "alternatives": [{"letter": "A", "text": "Acúmulo de gás etileno.", "file": null}, {"letter": "B", "text": "Redução da umidade do ar.", "file": null}, {"letter": "C", "text": "Aumento na concentração de CO2.", "file": null}, {"letter": "D", "text": "Diminuição da intensidade luminosa.", "file": null}, {"letter": "E", "text": "Isolamento do contato com O2 atmosférico.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/97", "created_at": "2026-10-27T00:00:00Z"}, {"id": "enem-2023-98-geral", "year": 2023, "number": 98, "discipline": "ciencias-humanas", "language": null, "context": "Há muito tempo são conhecidas espécies de lesmas-do-mar com uma capacidade impar: guardar parte da maquinaria das células das algas que consomem — os cloroplastos — e mantê-los funcionais dentro das suas próprias células, obtendo assim parte do seu alimento. Investigadores portugueses descobriram que essas lesmas-do-mar podem ser mais eficientes nesse processo do que as próprias algas que consomem.\n\nDisponível em: www.cienciahoje.pt. Acesso em: 10 fev. 2015 (adaptado).", "prompt": "Essa adaptação confere a esse organismo a capacidade de obter primariamente", "alternatives": [{"letter": "A", "text": "Ácidos necleicos.", "file": null}, {"letter": "B", "text": "Carboidratos.", "file": null}, {"letter": "C", "text": "Proteínas.", "file": null}, {"letter": "D", "text": "Vitaminas.", "file": null}, {"letter": "E", "text": "Lipídios.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/98", "created_at": "2026-10-27T00:00:00Z"}, {"id": "enem-2023-99-geral", "year": 2023, "number": 99, "discipline": "ciencias-natureza", "language": null, "context": "", "prompt": "A leishmaniose visceral é uma zoonose causada por um protozoário do gênero Leishmania que é encontrado em diversos tecidos. Ela é transmitida ao homem de forma indireta, por vetores do ambiente doméstico. O cão é considerado um importante hospedeiro desse protozoário, podendo ou não apresentar os sintomas da doença, como perda de peso, anemia, ferimentos na pele, diarreia, conjuntivite e insuficiência renal. Em uma região que sofre com alta incidência dessa doença, uma campanha do centro de zoonoses buscou verificar a presença desse protozoário nos cães para tentar controlar a doença.", "alternatives": [{"letter": "A", "text": "Urina.", "file": null}, {"letter": "B", "text": "Saliva.", "file": null}, {"letter": "C", "text": "Fezes.", "file": null}, {"letter": "D", "text": "Sangue.", "file": null}, {"letter": "E", "text": "Secreção ocular.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/99", "created_at": "2026-10-27T00:00:00Z"}, {"id": "enem-2023-100-geral", "year": 2023, "number": 100, "discipline": "ciencias-natureza", "language": null, "context": "Um professor lança uma esfera verticalmente para cima, a qual retorna, depois de alguns segundos, ao ponto de lançamento. Em seguida, lista em um quadro todas as possibilidades para as grandezas cinemáticas.\n\n![](https://enem.dev/2023/questions/100/92848aa5-da82-4c66-9945-7051120a42c9.jpg)", "prompt": "Ele solicita aos alunos que analisem as grandezas cinemáticas no instante em que a esfera atinge a altura máxima, escolhendo uma combinação para os módulos e sentidos da velocidade e da aceleração. A escolha que corresponde à combinação correta é", "alternatives": [{"letter": "A", "text": "V = 0 e a ≠ 0 para cima.", "file": null}, {"letter": "B", "text": "V ≠ 0 para cima e a = 0", "file": null}, {"letter": "C", "text": "V = 0 e a ≠ 0 para baixo.", "file": null}, {"letter": "D", "text": "V ≠ 0 para cima e a ≠ 0 para cima.", "file": null}, {"letter": "E", "text": "V ≠ 0 para baixo e a ≠ 0 para baixo.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/100", "created_at": "2026-10-27T00:00:00Z"}, {"id": "enem-2023-101-geral", "year": 2023, "number": 101, "discipline": "ciencias-natureza", "language": null, "context": "", "prompt": "Muitas mulheres sofrem com desconfortos nos dias que antecedem a menstruação, a chamada tensão pré-menstrual. Entre outros sintomas, podem ocorrer alterações de humor. Atualmente, acredita-se que os sintomas são resultado da queda na concentração do neurotransmissor serotonina, que, por sua vez, está relacionado com a diminuição na produção dos hormônios ovarianos estrógeno e progesterona, observada nessa fase do ciclo feminino.\nDIMMOCK, P. W. et al. Efficacy of Selective Serotonin-Reuptake Inhibitors in Premenstrual Syndrome: a Systematic Review. The Lancet, n. 9 236, 2000 (adaptado).\nA redução da produção desses hormônios nessa fase está relacionada com o(a)", "alternatives": [{"letter": "A", "text": "Regressão do corpo lúteo ovariano.", "file": null}, {"letter": "B", "text": "Diminuição na produção de ocitocina.", "file": null}, {"letter": "C", "text": "Liberação do gameta feminino na ovulação.", "file": null}, {"letter": "D", "text": "Aumento nos níveis dos hormônios LH e FSH.", "file": null}, {"letter": "E", "text": "Elevação nos níveis sorológicos de adrenalina.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/101", "created_at": "2026-10-27T00:00:00Z"}, {"id": "enem-2023-102-geral", "year": 2023, "number": 102, "discipline": "ciencias-natureza", "language": null, "context": "", "prompt": "As cetonas fazem parte de famílias olfativas encontradas em muitos alimentos. A molécula de hexan-3-ona é um exemplo desses compostos voláteis responsáveis pelo aroma, podendo ser obtida por processos energéticos realizados em meio ácido, na presença de oxidantes como o permanganato de potássio. Para se produzir esse composto volátil em laboratório, deve-se oxidar a molécula de", "alternatives": [{"letter": "A", "text": "Hexanal.", "file": null}, {"letter": "B", "text": "Hexan-1-ol.", "file": null}, {"letter": "C", "text": "Hexan-3-ol.", "file": null}, {"letter": "D", "text": "Hex-1-en-1-ol.", "file": null}, {"letter": "E", "text": "Ácido hexanoico.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/102", "created_at": "2026-10-27T00:00:00Z"}, {"id": "enem-2023-103-geral", "year": 2023, "number": 103, "discipline": "ciencias-natureza", "language": null, "context": "", "prompt": "Durante a evolução das plantas, ocorreu uma transição do ambiente aquático para o ambiente terrestre graças ao surgimento de algumas estruturas que as tornaram independentes da água. Esse fato permitiu maior dispersão desse grupo de seres vivos, sendo possível observá-los em diferentes ambientes na atualidade.\nQual estrutura possibilitou a independência da água para a fecundação dos seres vivos citados acima?", "alternatives": [{"letter": "A", "text": "Fruto.", "file": null}, {"letter": "B", "text": "Esporo.", "file": null}, {"letter": "C", "text": "Semente.", "file": null}, {"letter": "D", "text": "Tubo polínico.", "file": null}, {"letter": "E", "text": "Vaso condutor.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/103", "created_at": "2026-10-27T00:00:00Z"}, {"id": "enem-2023-104-geral", "year": 2023, "number": 104, "discipline": "ciencias-natureza", "language": null, "context": "O vidro contendo alumínio em sua composição é um excelente material para acondicionar medicamentos e suplementos, porque pode ser esterilizado por aquecimento. No entanto, quando o medicamento ou suplemento contém substâncias que se ligam fortemente ao íon desse metal, a dissolução do alumínio é promovida em função do deslocamento do equilíbrio químico estabelecido entre a espécie imobilizada no vidro e a espécie em solução. Por essa razão, recomenda-se que suplementos de nutrição de recém-nascidos contendo gluconato de cálcio sejam acondicionados em embalagens plásticas, e não nesse tipo de vidro.\n\n**Atualização da recomendação da Sociedade Portuguesa de Neonatologia.**  \nDisponível em: www.spneonatologia.pt. Acesso em: 22 out. 2021 (adaptado).", "prompt": "Caso esse suplemento seja acondicionado em embalagem desse tipo de vidro, o risco de contaminação por alumínio será maior se o(a)", "alternatives": [{"letter": "A", "text": "Vidro do frasco for translúcido.", "file": null}, {"letter": "B", "text": "Concentração de gluconato de cálcio for alta.", "file": null}, {"letter": "C", "text": "Frasco de vidro apresentar uma maior espessura.", "file": null}, {"letter": "D", "text": "Vidro for previamente esterilizado em altas temperaturas.", "file": null}, {"letter": "E", "text": "Reação do alumínio com gluconato de cálcio for endotérmica.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/104", "created_at": "2026-10-27T00:00:00Z"}, {"id": "enem-2023-105-geral", "year": 2023, "number": 105, "discipline": "ciencias-natureza", "language": null, "context": "Barbatimão é o nome popular de uma árvore cuja casca e utilizada para fins medicinais. Essa casca é constituída principalmente de dois tecidos vegetais: periderme e floema. A extração da casca tem levado à morte muitos indivíduos dessa espécie, quando o corte retira um anel completo ao longo da circunferência do tronco. Aqueles que têm parte da casca retirada sem completar essa circunferência podem sobreviver.", "prompt": "A morte desses indivíduos, decorrente da retirada do anel completo da casca, é provocada pela interrupção da", "alternatives": [{"letter": "A", "text": "Fotossíntese.", "file": null}, {"letter": "B", "text": "Transpiração.", "file": null}, {"letter": "C", "text": "Troca de gases.", "file": null}, {"letter": "D", "text": "Formação de brotos.", "file": null}, {"letter": "E", "text": "Nutrição das raízes.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/105", "created_at": "2026-10-27T00:00:00Z"}, {"id": "enem-2023-106-geral", "year": 2023, "number": 106, "discipline": "ciencias-natureza", "language": null, "context": "A tecnologia de vacinas de RNA mensageiro (RNAm) é investigada há anos. Avanços científicos em genética molecular permitiram desenvolver uma vacina para controle da pandemia da covid-19 causada pelo vírus de RNA SARS-CoV-2. A vacina de RNAm tem sequências de genes do vírus. Entretanto, por ser muito instável, o RNAm deve ser recoberto por uma capa de lipídios que evita sua degradação e favorece sua ação. Dessa forma, o RNAm desempenhará sua função especifica atuando no mesmo compartimento celular de sempre.\n\nDisponível em: https://sbim.org.br. Acesso em: 29 nov. 2021 (adaptado).", "prompt": "A imunização produzida por esse tipo de vacina é alcançada por meio da", "alternatives": [{"letter": "A", "text": "Estimulação de leucócitos induzida pela capa lipídica contendo RNAm.", "file": null}, {"letter": "B", "text": "Atuação do RNAm como sequestrador do vírus para o meio extracelular.", "file": null}, {"letter": "C", "text": "Tradução do RNAm em proteína viral, desencadeando a resposta antigênica.", "file": null}, {"letter": "D", "text": "Competição entre o RNAm vacinal e o RNA viral pelos sítios dos ribossomos.", "file": null}, {"letter": "E", "text": "Incorporação do RNAm viral ao genoma do hospedeiro. gerando novo fenótipo.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/106", "created_at": "2026-10-27T00:00:00Z"}, {"id": "enem-2023-107-geral", "year": 2023, "number": 107, "discipline": "ciencias-natureza", "language": null, "context": "Na fertilização in vitro, espermatozoides são adicionados aos gametas femininos retirados de uma mulher. Após o período de incubação, a fecundação é favorecida pela ação de enzimas. Em um procedimento realizado, observou-se que nenhum dos gametas femininos foi fertilizado e, posteriormente, verificou-se que havia sido adicionado, equivocadamente, um coquetel de inibidores das enzimas do acrossomo, no lugar de um dos nutrientes constituintes do meio de cultura.", "prompt": "O coquetel de inibidores impediu o(a)", "alternatives": [{"letter": "A", "text": "Formação do pronúcleo masculino.", "file": null}, {"letter": "B", "text": "Início da divisão mitótica do zigoto.", "file": null}, {"letter": "C", "text": "Término da segunda divisão meiótica do ovócito.", "file": null}, {"letter": "D", "text": "Passagem do espermatozoide pela corona radiata e zona pelúcida.", "file": null}, {"letter": "E", "text": "Fusão das membranas plasmáticas do ovócito e do espermatozoide.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/107", "created_at": "2026-10-27T00:00:00Z"}, {"id": "enem-2023-108-geral", "year": 2023, "number": 108, "discipline": "ciencias-natureza", "language": null, "context": "", "prompt": "O fogão por indução funciona a partir do surgimento de uma corrente elétrica induzida no fundo da panela, com consequente transformação de energia elétrica em calor por efeito Joule. A principal vantagem desses fogões é a eficiência energética, que é substancialmente maior que a dos fogões convencionais.\nA corrente elétrica mencionada é induzida por", "alternatives": [{"letter": "A", "text": "Radiação.", "file": null}, {"letter": "B", "text": "Condução.", "file": null}, {"letter": "C", "text": "Campo elétrico variável.", "file": null}, {"letter": "D", "text": "Campo magnético variável.", "file": null}, {"letter": "E", "text": "Ressonância eletromagnética.", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/108", "created_at": "2026-10-27T00:00:00Z"}, {"id": "enem-2023-109-geral", "year": 2023, "number": 109, "discipline": "ciencias-humanas", "language": null, "context": "Uma academia decide trocar gradualmente seus aparelhos de musculação. Agora, os frequentadores que utilizam os aparelhos do tipo 1 podem também utilizar os aparelhos do tipo 2, representados na figura, para elevar cargas correspondentes às massas M1 e M2 com velocidade constante. A fim de que o exercício seja realizado com a mesma força F, os usuários devem ser orientados a respeito da relação entre as cargas nos dois tipos de aparelhos, já que as polias fixas apenas mudam a direção das forças, enquanto a polia móvel divide as forças.\n\nEm ambos os aparelhos, considere as cordas inextensíveis, as massas das polias e das cordas desprezíveis e que não há dissipação de energia.\n\n![](https://enem.dev/2023/questions/109/e083688b-cc00-4c8b-9de6-01f07a7a6a5c.png)", "prompt": "Para essa academia, qual deve ser a razão M2/M1 informada aos usuários?", "alternatives": [{"letter": "A", "text": "1/4", "file": null}, {"letter": "B", "text": "1/2", "file": null}, {"letter": "C", "text": "1", "file": null}, {"letter": "D", "text": "2", "file": null}, {"letter": "E", "text": "4", "file": null}], "source_url": "https://api.enem.dev/v1/exams/2023/questions/109", "created_at": "2026-10-27T00:00:00Z"}]'::jsonb);
